import type { Page } from '@playwright/test';

// The dev server proxies every /petclinic/* path to the backend, so the app is only
// reachable from the root URL. Reach owner screens through the navbar, not a deep link.
export async function openOwnersList(page: Page, url: string) {
    await page.goto(url);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
}

export async function openNewOwnerForm(page: Page, url: string) {
    await page.goto(url);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Add New" }).click();
}

export async function fillOwnerForm(
    page: Page,
    firstName: string,
    lastName: string,
    address: string,
    city: string,
    telephone: string,
    email: string,
) {
    await page.locator("#firstName").fill(firstName);
    await page.locator("#lastName").fill(lastName);
    await page.locator("#address").fill(address);
    await page.locator("#city").fill(city);
    await page.locator("#telephone").fill(telephone);
    await page.locator("#email").fill(email);
}
